// cpp: foundation/graphics_types/graphics/blend_mode.h:31-54
fn blend_mode_from_bits(bits: u32) -> BlendMode {
    match bits {
        0 => BlendMode::kNormal,
        1 => BlendMode::kMultiply,
        2 => BlendMode::kScreen,
        3 => BlendMode::kOverlay,
        4 => BlendMode::kDarken,
        5 => BlendMode::kLighten,
        6 => BlendMode::kColorDodge,
        7 => BlendMode::kColorBurn,
        8 => BlendMode::kHardLight,
        9 => BlendMode::kSoftLight,
        10 => BlendMode::kDifference,
        11 => BlendMode::kExclusion,
        12 => BlendMode::kHue,
        13 => BlendMode::kSaturation,
        14 => BlendMode::kColor,
        15 => BlendMode::kLuminosity,
        16 => BlendMode::kPlusLighter,
        _ => unreachable!("blend-mode bitfield contains no enum value"),
    }
}

