// cpp: foundation/style_values/style/computed_style_base_constants.h:312-326
fn dominant_baseline_from_bits(bits: u32) -> EDominantBaseline {
    match bits {
        0 => EDominantBaseline::kMiddle,
        1 => EDominantBaseline::kAuto,
        2 => EDominantBaseline::kAlphabetic,
        3 => EDominantBaseline::kCentral,
        4 => EDominantBaseline::kTextBeforeEdge,
        5 => EDominantBaseline::kTextAfterEdge,
        6 => EDominantBaseline::kIdeographic,
        7 => EDominantBaseline::kHanging,
        8 => EDominantBaseline::kMathematical,
        9 => EDominantBaseline::kUseScript,
        10 => EDominantBaseline::kNoChange,
        11 => EDominantBaseline::kResetSize,
        _ => unreachable!("EDominantBaseline bitfield contains no enum value"),
    }
}

