// cpp: foundation/style_values/style/computed_style_base_constants.h:273-310
fn display_from_bits(bits: u32) -> EDisplay {
    match bits {
        0 => EDisplay::kInline,
        1 => EDisplay::kBlock,
        2 => EDisplay::kListItem,
        3 => EDisplay::kInlineBlock,
        4 => EDisplay::kTable,
        5 => EDisplay::kInlineTable,
        6 => EDisplay::kTableRowGroup,
        7 => EDisplay::kTableHeaderGroup,
        8 => EDisplay::kTableFooterGroup,
        9 => EDisplay::kTableRow,
        10 => EDisplay::kTableColumnGroup,
        11 => EDisplay::kTableColumn,
        12 => EDisplay::kTableCell,
        13 => EDisplay::kTableCaption,
        14 => EDisplay::kWebkitBox,
        15 => EDisplay::kWebkitInlineBox,
        16 => EDisplay::kFlex,
        17 => EDisplay::kInlineFlex,
        18 => EDisplay::kGrid,
        19 => EDisplay::kInlineGrid,
        20 => EDisplay::kContents,
        21 => EDisplay::kFlowRoot,
        22 => EDisplay::kNone,
        23 => EDisplay::kLayoutCustom,
        24 => EDisplay::kInlineLayoutCustom,
        25 => EDisplay::kMath,
        26 => EDisplay::kBlockMath,
        27 => EDisplay::kInlineListItem,
        28 => EDisplay::kFlowRootListItem,
        29 => EDisplay::kInlineFlowRootListItem,
        30 => EDisplay::kRuby,
        31 => EDisplay::kBlockRuby,
        32 => EDisplay::kRubyText,
        33 => EDisplay::kGridLanes,
        34 => EDisplay::kInlineGridLanes,
        _ => unreachable!("display bitfield contains no enum value"),
    }
}

