// cpp: foundation/style_values/style/computed_style_base_constants.h:364-369
fn forced_color_adjust_from_bits(bits: u32) -> EForcedColorAdjust {
    match bits {
        0 => EForcedColorAdjust::kNone,
        1 => EForcedColorAdjust::kAuto,
        2 => EForcedColorAdjust::kPreserveParentColor,
        _ => unreachable!("forced-color-adjust bitfield contains no enum value"),
    }
}

// cpp: foundation/style_values/style/computed_style_base_constants.h:371-378
fn frame_sizing_from_bits(bits: u32) -> EFrameSizing {
    match bits {
        0 => EFrameSizing::kAuto,
        1 => EFrameSizing::kContentWidth,
        2 => EFrameSizing::kContentHeight,
        3 => EFrameSizing::kContentBlockSize,
        4 => EFrameSizing::kContentInlineSize,
        _ => unreachable!("frame-sizing bitfield contains no enum value"),
    }
}

