// cpp: foundation/style_values/style/computed_style_base_constants.h:474-482
fn object_fit_from_bit(bit: u32) -> EObjectFit {
    match bit {
        0 => EObjectFit::kNone,
        1 => EObjectFit::kContain,
        2 => EObjectFit::kCover,
        3 => EObjectFit::kFill,
        4 => EObjectFit::kScaleDown,
        _ => unreachable!("invalid object-fit bitfield value"),
    }
}

