// cpp: foundation/style_values/style/computed_style_base_constants.h:678-682
fn table_layout_from_bit(bit: u32) -> ETableLayout {
    match bit {
        0 => ETableLayout::kAuto,
        1 => ETableLayout::kFixed,
        _ => unreachable!("invalid table-layout bitfield value"),
    }
}

