// Each generated C++ data group's Trace(Visitor*) was translated above.
// Bind those existing bodies to the target heap's tracing contract instead
// of substituting a no-op collector hook.
macro_rules! impl_style_data_traceable {
    ($($name:ty),* $(,)?) => {
        $(impl foundation::Traceable for $name {
            fn Trace(&self, visitor: &mut foundation::Visitor<'_>) {
                <$name>::Trace(self, visitor);
            }
        })*
    };
}

