fn css_variable_data_equal(
    a: &super::forward::CSSVariableData,
    b: &super::forward::CSSVariableData,
) -> bool {
    if std::ptr::eq(a, b) {
        return true;
    }
    unimplemented!("distinct CSSVariableData requires the owning CSS token-stream payload")
}
